class ListNode {
  constructor(val, next = null) { this.val = val; this.next = next; }
}
function buildList(values) {
  let head = null, tail = null;
  for (const v of values) {
    const node = new ListNode(v);
    if (!head) head = node; else tail.next = node;
    tail = node;
  }
  return head;
}
